// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address participant) public {
        vm.assume(participant != address(0) && participant != address(c.bank()));
        uint amount = 10;
        vm.deal(participant, amount);

        uint potBefore = c.pot();

        vm.prank(participant);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("play()"));

        uint potAfter = c.pot();

        // General rule: pot increases by exactly amount (not amount+1) when call succeeds
        assertTrue(!success || potAfter == potBefore + amount);
    }
}

